inheritance-design.q:
Может ли work() вернуть this как Base*?

struct Base {};
class Derived : private Base {
public:
    Base* work() { return this; }
};

rtti-design.q:
Что напечатает программа?

#include <iostream>
#include <typeinfo>
struct Base {};
struct Derived : Base {};
int main() {
    Derived object;
    Base& ref = object;
    std::cout << (typeid(ref) == typeid(Base));
}
